2	// One-shot seeder that imports the tag taxonomy from
3	// docs/tag_taxonomy_3_tiers.md.
4	//
5	// Tier rules:
6	//  - Tier 1 -> isAdult = false (safe, default-visible)
7	//  - Tier 2 -> isAdult = true  (gray-area / explicit mainstream)
8	//  - Tier 3 -> isAdult = true  (extreme / dead-dove)
9	//
10	// Run with:
11	//   npm run seed:tags
12	//
13	// The script is idempotent: it upserts on tag name (lower-cased),
14	// so re-running won't create duplicates and will update isAdult to
15	// match the taxonomy if it changed.
16	
17	import { existsSync, readFileSync } from 'node:fs';
18	import { resolve } from 'node:path';
19	import { PrismaClient } from '@prisma/client';
20	import { slugify } from '../src/common/utils/slug';
21	
22	const TAXONOMY_PATH = resolve(__dirname, '..', '..', 'docs', 'tag_taxonomy_3_tiers.md');
23	const EXTRAS_PATH = resolve(__dirname, '..', '..', 'docs', 'tag_extras.json');
24	
25	interface ParsedTag {
26	  name: string;
27	  isAdult: boolean;
28	}
29	
30	function parseTaxonomy(markdown: string): ParsedTag[] {
31	  const lines = markdown.split(/\r?\n/);
32	  const out: ParsedTag[] = [];
33	  const seen = new Set<string>();
34	
35	  let currentTier: 1 | 2 | 3 | null = null;
36	
37	  for (const raw of lines) {
38	    const tierMatch = raw.match(/^##\s+TIER\s+([123])\b/i);
39	    if (tierMatch) {
40	      currentTier = Number(tierMatch[1]) as 1 | 2 | 3;
41	      continue;
42	    }
43	
44	    if (currentTier === null) continue;
45	
46	    // Bullet item
47	    const bulletMatch = raw.match(/^\s*-\s+(.*)$/);
48	    if (!bulletMatch) continue;
49	
50	    let line = bulletMatch[1];
51	
52	    // Drop emojis (anything non-ASCII / non-whitespace) — keeps the
53	    // structure clean. Em-dashes stay because they're inside ASCII.
54	    line = line.replace(/[^\x00-\x7F]/g, '').trim();
55	    if (!line) continue;
56	
57	    // Drop parenthetical descriptions: "M/F (Het / Straight)" -> "M/F"
58	    line = line.replace(/\s*\([^)]*\)/g, '').trim();
59	    if (!line) continue;
60	
61	    // Drop trailing rating numbers like "/ 0", "/ 1", "/ 6+".
62	    line = line.replace(/\s*\/\s*\d+\+?\s*$/, '').trim();
63	
64	    // Heuristic: a long comma list ("CEO, Doctor, Nurse, ...") is
65	    // multiple tags. A short line ("Past Sexual Assault (off-page)")
66	    // is one tag with a comma in its description.
67	    let parts: string[];
68	    if ((line.match(/,/g) || []).length >= 3) {
69	      parts = line.split(/,/g).map((p) => p.trim());
70	    } else {
71	      parts = [line];
72	    }
73	
74	    for (let part of parts) {
75	      // Trailing punctuation cleanup
76	      part = part.replace(/[\s\-:]+$/, '').trim();
77	      if (!part) continue;
78	      // Skip pure-number "tags" (heat-rating remnants like "0", "1")
79	      if (/^\d+\+?$/.test(part)) continue;
